(* [comment removed for export] *)
Ltac split_ins T i vsp vx K :=
  lazymatch T with
  | forall x : ?A, @?B x =>
      let y := fresh "y" in
      constr:(forall y : A, ltac:(
        let b := eval cbv beta in (B y) in
        let j := eval cbv in (S i) in
        let r := lazymatch j with
                 | 4%nat => split_ins b j y vx K
                 | 39%nat => split_ins b j vsp y K
                 | _ => split_ins b j vsp vx K
                 end in
        exact r))
  | _ => let p := K vsp vx in constr:(p -> T)
  end.
Section CV.
Variable RT : rt_sig.
Hypothesis AF : art_facts RT.
Hypothesis GP : rt_gaps RT.
Hypothesis FKC : rt_fk_contracts RT.   (* [comment removed for export] *)
Hypothesis STDERR : lept_stderr_cpsF RT.
Hypothesis RERR : returnError_cpsF RT e_returnErrorInt.
Hypothesis MAXIDX : pixGetMaxColorIndex_cpsF RT.

Definition pixcmapIsValid_ok_P16_stmt : Prop :=
  ltac:(let T := eval cbv delta [pixcmapIsValid_cpsF] beta in (pixcmapIsValid_cpsF RT) in
        let r := split_ins T 0%nat tt tt ltac:(fun sp pix => constr:(bv_unsigned sp mod 32 <> 0 /\ pix <> 0)) in exact r).
